mapper.select:
        select sum(mete)                 mete,
               sum(quantity)             quantity,
               sum(input_VAT)            inputVAT,
               sum(amount)               amount,
               sum(amount_excluding_VAT) amountExcludingVAT
        from wms_statistics_begin_period
        where bool_delete_enum = 0
          and statistics_id = #{id}
            and  create_time > #{times.startTime}
            and  create_time < #{times.endTime}

select wsbp.*, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, pm.name pmName, pa.name paName, mbf.id mbfId, mbf.name mbfName, wc.name classifyName, ww.id wwId, ww.name wwName from wms_statistics_begin_period wsbp left join contract_project p on p.id = wsbp.project_id left join wms_workshop mbf on wsbp.workshop_id = mbf.id left join wms_warehouse ww on ww.id = wsbp.warehouse_id left join wms_classification wc on wsbp.classify_id = wc.id left join plan_monomer pm on pm.id = wsbp.monomer_id left join plan_area pa on pa.id = wsbp.area_id where wsbp.bool_delete_enum = 0 and wsbp.mete is not null
and wsbp.statistics_id in
#{item}
and wsbp.wms_closing_time_id=#{times.wmsClosingTimeId}
and wsbp.create_time > #{times.startTime}
and wsbp.create_time < #{times.endTime}

select wsbp.*, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, pm.name pmName, pa.name paName, mbf.id mbfId, mbf.name mbfName, wc.name classifyName, ww.id wwId, ww.name wwName from wms_statistics_begin_period wsbp left join contract_project p on p.id = wsbp.project_id left join wms_workshop mbf on wsbp.workshop_id = mbf.id left join wms_warehouse ww on ww.id = wsbp.warehouse_id left join wms_classification wc on wsbp.classify_id = wc.id left join plan_monomer pm on pm.id = wsbp.monomer_id left join plan_area pa on pa.id = wsbp.area_id where wsbp.bool_delete_enum = 0 and wsbp.mete is not null and wsbp.create_time > #{times.startTime} and wsbp.create_time < #{times.endTime}
and wsbp.statistics_id in
#{item}

        select ifnull(SUM(amount_excluding_vat),0)
        from wms_statistics_begin_period
        where bool_delete_enum = 0
        
            and   wms_closing_time_id=#{times.wmsClosingTimeId}
        
        
            and   wms_closing_time_id is null
        
        
            and   create_time>#{times.startTime}
        
        
            and  create_time < #{times.endTime}

SELECT CASE WHEN DATE_FORMAT( create_time, '%m' ) = '01' THEN '12' ELSE LPAD( DATE_FORMAT( create_time, '%m' ) - 1, 2, '0' ) END AS DATE, ifnull(sum(mete),0) mete, CASE WHEN #{type} = 1 THEN sum(ifnull(amount, 0)) WHEN #{type} = 2 THEN sum(ifnull(amount_excluding_vat, 0)) END amount FROM wms_statistics_begin_period WHERE bool_delete_enum = 0 AND ( (YEAR(create_time) = YEAR(#{yearDate}) AND MONTH(create_time) >= 2) OR (YEAR(create_time) = YEAR(#{yearDate}) + 1 AND MONTH(create_time) = 1) )
and material_is_whole = #{materialIsWhole}
and basic_class & #{basicClass} > 0
AND EXISTS (SELECT 1 FROM wms_workshop ww JOIN mes_building_factory mf ON mf.id=ww.factory_id AND mf.bool_delete_enum=0 WHERE ww.bool_delete_enum=0 AND ww.id=wms_statistics_begin_period.workshop_id AND mf.branch_company_id=#{branchCompanyId})
GROUP BY CASE WHEN DATE_FORMAT( create_time, '%m' ) = '01' THEN '12' ELSE LPAD( DATE_FORMAT( create_time, '%m' ) - 1, 2, '0' ) END;

        SELECT
            CASE
                WHEN count(*) = 0 THEN
                    1
                WHEN count(*) > 0 THEN
                    0
                END
        FROM
            wms_statistics_begin_period
            WHERE
            bool_delete_enum = 0
        AND date_format( create_time, '%Y' ) = date_format( now(), '%Y' )
        and basic_class = #{basicClass}
        and classify_id = #{classifyId}
        and bool_party_a = #{boolPartyA}
        
            and workshop_id = #{workshopId}
        
        
            and material_is_whole = #{materialIsWhole}
        
        
            and standard_id = #{standardId}
        
        
            AND warehouse_id = #{warehouseId}
        
        
            AND specification = #{specification}
        
        
            AND specification is null
        
        
            AND length = #{length}
        
        
            AND length is null
        
        
            AND width = #{width}
        
        
            AND width is null
        
        
            AND thickness = #{thickness}
        
        
            AND thickness is null
        
        
            AND unit_net = #{unitNet}
        
        
            AND unit_net is null
        
        
            AND project_id = #{projectId}
        
        
            AND project_id is null
        
        
            AND heat_no_and_batch_no = #{heatNoAndBatchNo}
        
        
            AND heat_no_and_batch_no is null
        
        
            AND brand = #{brand}
        
        
            AND brand is null
        
        
            AND color = #{color}
        
        
            AND color is null

select statistics_id AS id, sum(mete) AS mete, sum(quantity) AS quantity, sum(input_VAT) AS inputVAT, sum(amount) AS amount, sum(amount_excluding_VAT) AS amountExcludingVAT from wms_statistics_begin_period where bool_delete_enum = 0
and wms_closing_time_id=#{times.wmsClosingTimeId}
and wms_closing_time_id is null
and create_time < #{times.endTime}
and statistics_id in
#{id}
and create_time > #{times.startTime}
and create_time < #{times.endTime}
group by statistics_id

select IFNULL(SUM(amount_excluding_vat),0)
from wms_statistics_begin_period
where bool_delete_enum = 0
  and create_time > #{times.startTime}
  and create_time < #{times.endTime}
  
      and basic_class & #{basicClass} > 0
  
  
      and workshop_id = #{workshopId}
  
  
      and classify_id in
      
          #{classifyId}

select IFNULL(SUM(mete),0)
from wms_statistics_begin_period
where bool_delete_enum = 0
and create_time > #{times.startTime}
and create_time < #{times.endTime}

